-- Preserve rows and assignments; retire migration-generated buttons without an actual system endpoint.
-- Source DDL already supplies start_time/end_time; only the measured duration is new.
ALTER TABLE sys_job_log ADD COLUMN cost_time BIGINT NULL;
UPDATE sys_menu SET status='1',visible='1' WHERE create_by='migration' AND menu_type='F' AND (perms LIKE 'system:%' OR perms LIKE 'monitor:%') AND perms NOT IN ('foundation:access:read','foundation:erp:inspect','monitor:cache:list','monitor:druid:list','monitor:job:add','monitor:job:changeStatus','monitor:job:edit','monitor:job:export','monitor:job:list','monitor:job:query','monitor:job:remove','monitor:logininfor:export','monitor:logininfor:list','monitor:logininfor:remove','monitor:online:forceLogout','monitor:online:list','monitor:operlog:export','monitor:operlog:list','monitor:operlog:remove','monitor:server:list','platform:configs:read','platform:configs:write','platform:dict-data:read','platform:dict-data:write','platform:dict-types:read','platform:dict-types:write','platform:jobs:read','platform:jobs:run','platform:jobs:write','platform:logs:read','platform:menus:read','platform:menus:write','platform:roles:read','platform:roles:write','platform:users:read','platform:users:write','system:autocode:part:insert','system:autocode:part:list','system:autocode:part:query','system:autocode:part:remove','system:autocode:part:update','system:autocode:rule:add','system:autocode:rule:edit','system:autocode:rule:generate','system:autocode:rule:list','system:autocode:rule:query','system:autocode:rule:remove','system:config:add','system:config:edit','system:config:export','system:config:list','system:config:query','system:config:remove','system:dept:add','system:dept:edit','system:dept:list','system:dept:query','system:dept:remove','system:dict:add','system:dict:edit','system:dict:export','system:dict:list','system:dict:query','system:dict:remove','system:menu:add','system:menu:edit','system:menu:list','system:menu:query','system:menu:remove','system:message:add','system:message:edit','system:message:export','system:message:list','system:message:query','system:message:remove','system:notice:add','system:notice:edit','system:notice:list','system:notice:query','system:notice:remove','system:post:add','system:post:edit','system:post:export','system:post:list','system:post:query','system:post:remove','system:role:add','system:role:edit','system:role:export','system:role:list','system:role:query','system:role:remove','system:user:add','system:user:edit','system:user:export','system:user:import','system:user:list','system:user:query','system:user:remove','system:user:resetPwd');
UPDATE sys_menu SET menu_name=CONCAT(SUBSTRING_INDEX(menu_name,' ',1),' · 列表') WHERE create_by='migration' AND menu_type='F' AND menu_name LIKE '% list';
